// Cloudflare entry: the OpenNext-built Next.js app, plus a cron job every minute that calls
// /api/cron (email/WhatsApp outbox and order housekeeping).
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";
import { createHmac } from "node:crypto";

type Env = { CRON_SECRET?: string; CLERK_SECRET_KEY?: string; NEXT_PUBLIC_SITE_URL?: string };
type Ctx = { waitUntil: (p: Promise<unknown>) => void };
// Same derivation as src/lib/secrets.ts
const cronSecret = (env: Env) =>
  env.CRON_SECRET || (env.CLERK_SECRET_KEY ? createHmac("sha256", env.CLERK_SECRET_KEY).update("gupta-enterprises:CRON_SECRET").digest("hex") : "");

const SHOP_HOST = "guptaenterpriseskohima.com";

/**
 * The shop has one address. http:// and www. used to answer with a second copy of every page,
 * which splits search ranking between the copies; they now move (permanently) to the same path
 * on https://guptaenterpriseskohima.com. Other hosts (workers.dev previews, localhost) pass through.
 */
function canonicalRedirect(req: Request): Response | null {
  const url = new URL(req.url);
  const host = url.hostname.toLowerCase();
  if (host !== SHOP_HOST && host !== `www.${SHOP_HOST}`) return null;
  if (host === SHOP_HOST && url.protocol === "https:") return null;
  url.protocol = "https:";
  url.hostname = SHOP_HOST;
  url.port = "";
  // 301 for page loads; 308 keeps the method and body for anything else
  const status = req.method === "GET" || req.method === "HEAD" ? 301 : 308;
  return new Response(null, { status, headers: { Location: url.toString(), "Cache-Control": "public, max-age=86400" } });
}

const worker = {
  fetch(req: Request, env: Env, ctx: Ctx) {
    return canonicalRedirect(req) ?? handler.fetch(req, env, ctx);
  },
  async scheduled(_event: unknown, env: Env, ctx: Ctx) {
    const req = new Request(`${env.NEXT_PUBLIC_SITE_URL ?? "https://guptaenterpriseskohima.com"}/api/cron`, {
      method: "POST",
      headers: { "x-cron-secret": cronSecret(env) },
    });
    ctx.waitUntil(handler.fetch(req, env, ctx));
  },
};
export default worker;

// @ts-expect-error: generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
